// ── Normalize Dodo webhook payload ────────────────────────────────────────
// Extracts only the fields that map to our live dodo_payments table:
//   payment_id, amount, currency, status, payment_method,
//   merchant_order_id, customer
//
// IMPORTANT: Dodo sends amounts in minor units (paise for INR).
//   ₹15.00 comes in as 1500 — we divide by 100 here.
//
// The backend /webhooks/dodo will perform the actual upsert, so this
// node just passes the raw event through with the svix/webhook headers
// preserved for signature verification.

const body = $input.item.json.body;
const headers = $input.item.json.headers;

// Pass event through — backend handles normalization and DB insert
return [{
  json: {
    // Forward the raw event body as-is (backend verifies signature)
    rawEvent: body,
    // Forward webhook signature headers so backend can verify
    forwardHeaders: {
      'webhook-id':        headers['webhook-id']        || headers['svix-id']        || '',
      'webhook-timestamp': headers['webhook-timestamp'] || headers['svix-timestamp'] || '',
      'webhook-signature': headers['webhook-signature'] || headers['svix-signature'] || '',
    },
    // Surface event type for n8n logging
    eventType: body.type || 'unknown',
    paymentId: (body.data || body).payment_id || null,
  }
}];
